import { useTranslation } from 'react-i18next'
import { useShellStore, type LeftPanelTab } from '@/app/store/shellStore'
import { AssistantPanel } from '@/features/assistant/AssistantPanel'
import { AppsPanel } from './AppsPanel'
import { ContextPanel } from './ContextPanel'
import { InboxPanel } from './InboxPanel'
import { clsx } from 'clsx'
import { Bot, LayoutGrid, Layers, Inbox } from 'lucide-react'

const TABS: { id: LeftPanelTab; icon: React.ReactNode; labelKey: string }[] = [
  { id: 'companion', icon: <Bot size={18} />, labelKey: 'companion' },
  { id: 'apps', icon: <LayoutGrid size={18} />, labelKey: 'apps' },
  { id: 'context', icon: <Layers size={18} />, labelKey: 'context' },
  { id: 'inbox', icon: <Inbox size={18} />, labelKey: 'inbox' },
]

export function LeftPanel() {
  const { t } = useTranslation('shell')
  const { leftPanelTab, leftPanelOpen, setLeftPanelTab } = useShellStore()

  if (!leftPanelOpen) return null

  return (
    <aside className="flex h-full w-72 flex-shrink-0 border-r border-border bg-surface flex-col">
      {/* Tab bar */}
      <div className="flex border-b border-border">
        {TABS.map((tab) => (
          <button
            key={tab.id}
            onClick={() => setLeftPanelTab(tab.id)}
            title={t(tab.labelKey)}
            className={clsx(
              'flex-1 flex flex-col items-center gap-0.5 py-2.5 text-xs font-medium transition-colors',
              leftPanelTab === tab.id
                ? 'text-accent border-b-2 border-accent bg-accent/5'
                : 'text-muted-foreground hover:text-foreground',
            )}
          >
            {tab.icon}
            <span className="hidden sm:block">{t(tab.labelKey)}</span>
          </button>
        ))}
      </div>

      {/* Tab content */}
      <div className="flex-1 overflow-hidden">
        {leftPanelTab === 'companion' && <AssistantPanel />}
        {leftPanelTab === 'apps' && <AppsPanel />}
        {leftPanelTab === 'context' && <ContextPanel />}
        {leftPanelTab === 'inbox' && <InboxPanel />}
      </div>
    </aside>
  )
}
